        if (hasEmail) {
            points += 2;
        }
        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (uniqueName) {
            points += 1;
        }
        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
